#include <stdio.h>
#include "transvoxel.h"

/* Tiny scalar field for an engine-independent example.
   Negative means solid, zero is the surface. */
static float field(TvVec3 p) {
    float hill = 1.35f - 0.18f * (p.x - 2.0f) * (p.x - 2.0f) - 0.18f * (p.z - 2.0f) * (p.z - 2.0f);
    return p.y - hill;
}

static TvVec3 add3(TvVec3 a, TvVec3 b) {
    TvVec3 out;
    out.x = a.x + b.x;
    out.y = a.y + b.y;
    out.z = a.z + b.z;
    return out;
}

static void write_triangle_obj(FILE *f, int *obj_index, const TvVec3 *vertices, const TvTriangle *triangles, int tri_count) {
    int i;
    for (i = 0; i < tri_count; ++i) {
        TvVec3 a = vertices[triangles[i].a];
        TvVec3 b = vertices[triangles[i].b];
        TvVec3 c = vertices[triangles[i].c];
        fprintf(f, "v %.6f %.6f %.6f\n", a.x, a.y, a.z);
        fprintf(f, "v %.6f %.6f %.6f\n", b.x, b.y, b.z);
        fprintf(f, "v %.6f %.6f %.6f\n", c.x, c.y, c.z);
        fprintf(f, "f %d %d %d\n", *obj_index, *obj_index + 1, *obj_index + 2);
        *obj_index += 3;
    }
}

static int emit_regular_cell(FILE *f, int *obj_index, TvVec3 origin) {
    float samples[TV_REGULAR_SAMPLE_COUNT];
    TvVec3 vertices[TV_REGULAR_MAX_VERTICES];
    TvTriangle triangles[TV_REGULAR_MAX_TRIANGLES];
    TvBuildInfo info;
    int i;

    for (i = 0; i < TV_REGULAR_SAMPLE_COUNT; ++i) {
        samples[i] = field(add3(origin, tv_regular_sample_position(i)));
    }

    info = tv_build_regular_cell(
        samples,
        0.0f,
        origin,
        tv_vec3(1.0f, 1.0f, 1.0f),
        vertices,
        TV_REGULAR_MAX_VERTICES,
        triangles,
        TV_REGULAR_MAX_TRIANGLES);

    if (info.result != TV_OK) {
        return info.result;
    }

    write_triangle_obj(f, obj_index, vertices, triangles, info.triangle_count);
    return TV_OK;
}

static int emit_transition_demo_cell(FILE *f, int *obj_index, TvVec3 origin) {
    float samples[TV_TRANSITION_SAMPLE_COUNT];
    TvVec3 vertices[TV_TRANSITION_MAX_VERTICES];
    TvTriangle triangles[TV_TRANSITION_MAX_TRIANGLES];
    TvBuildInfo info;
    int i;

    for (i = 0; i < TV_TRANSITION_SAMPLE_COUNT; ++i) {
        samples[i] = field(add3(origin, tv_transition_sample_position(i)));
    }

    /* For this standalone example, use the same conservative transition
       contract that the proof suite validates. Engines with real coarse LOD
       samples can fill all 14 samples directly instead. */
    tv_transition_fill_derived_samples(samples);

    info = tv_build_transition_cell(
        samples,
        0.0f,
        origin,
        tv_vec3(1.0f, 1.0f, 1.0f),
        vertices,
        TV_TRANSITION_MAX_VERTICES,
        triangles,
        TV_TRANSITION_MAX_TRIANGLES);

    if (info.result != TV_OK) {
        return info.result;
    }

    write_triangle_obj(f, obj_index, vertices, triangles, info.triangle_count);
    return TV_OK;
}

int main(void) {
    FILE *f = fopen("terrain_export.obj", "w");
    int obj_index = 1;
    int x;
    int y;
    int z;
    int rc;

    if (!f) {
        printf("failed to open terrain_export.obj\n");
        return 1;
    }

    fprintf(f, "# Generated by transvoxel_0bsd examples/c_terrain_export\n");
    fprintf(f, "# Vertices are intentionally duplicated for readability.\n");

    for (z = 0; z < 4; ++z) {
        for (y = 0; y < 3; ++y) {
            for (x = 0; x < 4; ++x) {
                rc = emit_regular_cell(f, &obj_index, tv_vec3((float)x, (float)y, (float)z));
                if (rc != TV_OK) {
                    fclose(f);
                    printf("regular cell failed result=%d\n", rc);
                    return 1;
                }
            }
        }
    }

    /* A small transition-cell strip beside the regular demo grid. This is not a
       full terrain engine; it only shows how the transition builder is called. */
    for (z = 0; z < 3; ++z) {
        rc = emit_transition_demo_cell(f, &obj_index, tv_vec3(5.0f, 0.0f, (float)z * 2.0f));
        if (rc != TV_OK) {
            fclose(f);
            printf("transition cell failed result=%d\n", rc);
            return 1;
        }
    }

    fclose(f);
    printf("wrote terrain_export.obj with %d OBJ vertices\n", obj_index - 1);
    return 0;
}
